mapper.select:
/* 아이템 이미지 파일 번호 조회 */
SELECT ATCH_FILE_SN
  FROM ITEM
 WHERE ITEM_SN = #{itemSn}

/* 상점 아이템 목록 조회(부위 필터) */ SELECT WHERE I.NTSL_YN = 'Y'
AND I.ITEM_REGN_CD = #{itemRegnCd}
ORDER BY I.ITEM_REGN_CD , I.SORT_SEQ , I.ITEM_SN

/* 일련번호로 판매 중 아이템 조회 */
SELECT 
 WHERE I.NTSL_YN = 'Y'
   AND I.ITEM_SN IN

        #{itemSn}

/* 굽기 대상 아이템 여부 */
SELECT COUNT(*)
  FROM ITEM
 WHERE ITEM_SN = #{itemSn}
   AND NTSL_YN = 'Y'
   AND BAKE_HINT IS NOT NULL

/* 관리자 아이템 목록 조회(판매 중지 포함, 부위 필터) */ SELECT I.ITEM_SN , I.ITEM_NM , I.ITEM_REGN_CD , C.COM_CD_NM AS ITEM_REGN_CD_NM , I.NEED_PNT , CASE WHEN I.NTSL_YN = 'Y' THEN TRUE ELSE FALSE END AS NTSL_YN , I.SORT_SEQ , I.ATCH_FILE_SN , I.BAKE_HINT , ( SELECT COUNT(*) FROM HLD_ITEM H JOIN PIXEL_CHAR P ON P.PIXEL_CHAR_SN = H.PIXEL_CHAR_SN AND P.DEL_YN = 'N' WHERE H.ITEM_SN = I.ITEM_SN AND H.DEL_YN = 'N' ) AS HLD_MBR_CNT FROM ITEM I LEFT JOIN COM_CD C ON C.COM_CD = I.ITEM_REGN_CD
I.ITEM_REGN_CD = #{itemRegnCd}
ORDER BY I.ITEM_REGN_CD , I.SORT_SEQ , I.ITEM_SN

/* 부위의 아이템 번호 목록 조회 */
SELECT ITEM_SN
  FROM ITEM
 WHERE ITEM_REGN_CD = #{itemRegnCd}
 ORDER BY SORT_SEQ
        , ITEM_SN

/* 부위의 마지막 정렬 순서 조회 */
SELECT COALESCE(MAX(SORT_SEQ), 0)
  FROM ITEM
 WHERE ITEM_REGN_CD = #{itemRegnCd}

mapper.insert:
/* 아이템 등록 */
INSERT INTO ITEM
     ( ATCH_FILE_SN
     , ITEM_REGN_CD
     , ITEM_NM
     , NEED_PNT
     , SORT_SEQ
     , NTSL_YN
     , BAKE_HINT
     , REG_DT
     , MDFCN_DT
     , RGTR_ID
     , MDFR_ID )
VALUES
     ( #{atchFileSn}
     , #{itemRegnCd}
     , #{itemNm}
     , #{needPnt}
     , #{sortSeq}
     , #{ntslYn}
     , #{bakeHint}
     , NOW()
     , NOW()
     , #{rgtrId}
     , #{mdfrId} )

mapper.update:
/* 아이템 수정(보낸 칸만) */
UPDATE ITEM
   SET MDFR_ID = #{item.mdfrId}
     , MDFCN_DT = NOW()

     , ATCH_FILE_SN = #{item.atchFileSn}


     , ITEM_REGN_CD = #{item.itemRegnCd}


     , ITEM_NM = #{item.itemNm}


     , NEED_PNT = #{item.needPnt}


     , SORT_SEQ = #{item.sortSeq}


     , NTSL_YN = #{item.ntslYn}


     , BAKE_HINT = #{item.bakeHint}

 WHERE ITEM_SN = #{item.itemSn}

/* 아이템 정렬 순서 수정 */
UPDATE ITEM
   SET SORT_SEQ = #{sortSeq}
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE ITEM_SN = #{itemSn}
